INSERT INTO public.services (category_id, name, type, description, sort_order) VALUES
('e00847f2-c28d-4e38-9413-636edd2361b0', 'Safety Plan Builder – Staff Reminder Guide', 'Clinical Tool – Safety Plan', 'Collaboratively build a written Safety Plan with the service user. Cover these 7 steps: (1) Warning signs – thoughts, moods, situations, behaviours that signal a crisis is building. (2) Internal coping strategies – things they can do alone to distract/self-soothe (music, walk, breathing, grounding). (3) Social contacts & settings for distraction – people and places that take their mind off the crisis (without discussing the crisis itself). (4) People they can ask for help – trusted friends/family with names and phone numbers. (5) Professionals & agencies to contact – Crisis Team, GP, NHS 111 (option 2), Samaritans 116 123. (6) Making the environment safe – remove or restrict access to means (medication, sharps, ligature points, alcohol). (7) One reason worth living – their personal motivation. Give them a copy, document in the record, and review at next contact.', 12),
('7d776a16-38bb-41c2-96ad-5d417a0524f5', 'Safety Plan Builder – Staff Reminder Guide', 'Clinical Tool – Safety Plan', 'Collaboratively build a written Safety Plan with the service user (Stanley-Brown model). Cover these 7 steps: (1) Warning signs – thoughts, images, moods, situations, behaviours that precede suicidal thinking. (2) Internal coping strategies – self-soothing actions they can do alone (music, exercise, grounding, breathing). (3) Social contacts & settings for distraction – people/places that take their mind off suicidal thoughts (no need to discuss the crisis). (4) People they can ask for help – named trusted friends/family with phone numbers. (5) Professionals & agencies – Crisis Team, GP, NHS 111 (option 2), Samaritans 116 123, A&E. (6) Means restriction – remove/secure medication, sharps, ligature points, firearms; involve family where appropriate. (7) Reasons for living – personal motivations to stay safe. Provide a written copy, document in the clinical record, and review at every subsequent contact.', 9);
